
  // URL Web App Apps Script aktif; endpoint publik hanya menerima action allowlist.
  const API_URL='https://script.google.com/macros/s/AKfycbyn364ZB5AYMws07WqeIeILpROYyP1HiZVooD0Zb00O0KYhhIrW6AmONLJ3UXk-OPiGSg/exec';
  const state={init:null,token:'',user:null,data:null,page:'home',search:'',filter:'ALL',classFilter:'ALL',pageNo:1,pageSize:8,taskPageNo:1,taskPageSize:5,submissionPageNo:1,modal:null,modalBackHtml:null,profilePhoto:'',photoRequested:false,periodStatusFilter:'ALL',classStatusFilter:'ALL',tasks:[],assessment:null,report:null,assessmentRequests:[],assessmentTab:'verify',assessmentByTab:{},assessmentRequestsByTab:{},assessmentFilters:{},assessmentLoadSeq:{},assessmentPages:{verify:1,table:1,entry:1},assessmentQueries:{verify:'',table:'',entry:''},assessmentComponentFilter:{table:'ALL',entry:'ALL'},proofDataCache:{},submissionStatusFilter:'submitted',missingTasks:[],missingQuery:''};
  const $=id=>document.getElementById(id);
  const esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const activeRows=(rows)=>Array.isArray(rows)?rows.filter(x=>String(x.status==null?'ACTIVE':x.status).trim().toUpperCase()==='ACTIVE'):[];
  const sortStudentsAlphabetically=(rows)=>[...(Array.isArray(rows)?rows:[])].sort((a,b)=>{const an=String(a.name||a.fullName||a.studentName||'').trim(),bn=String(b.name||b.fullName||b.studentName||'').trim();return an.localeCompare(bn,'id',{sensitivity:'base',numeric:true})||String(a.nisn||'').localeCompare(String(b.nisn||''),'id',{numeric:true})||String(a.id||'').localeCompare(String(b.id||''));});
  const optionEmpty=(label)=>`<option value="">${esc(label)}</option>`;
  const optionRows=(rows,label,valueFn,textFn,selected='')=>{const a=activeRows(rows);return optionEmpty(a.length?'Pilih '+label:'Tidak ada '+label+' aktif')+a.map(x=>{const v=String(valueFn(x)||'');return `<option value="${esc(v)}" ${v===String(selected)?'selected':''}>${esc(textFn(x))}</option>`}).join('')};
  const call=async(name,...args)=>{
    let response;
    try {
      const controller=new AbortController();
      const requestTimer=setTimeout(()=>controller.abort(),20000);
      try { response=await fetch(API_URL,{
        method:'POST',
        headers:{'Content-Type':'text/plain;charset=utf-8'},
        body:JSON.stringify({action:name,args}),
        cache:'no-store',redirect:'follow',signal:controller.signal
      }); } finally { clearTimeout(requestTimer); }
    } catch(e) {
      if(e && e.name==='AbortError') throw new Error('Koneksi ke server terlalu lama (lebih dari 20 detik). Muat ulang halaman dan periksa deployment Apps Script.');
      throw new Error('Tidak dapat menghubungi mesin NEDUKA TASK. Periksa koneksi internet atau deployment Apps Script.');
    }
    let payload;
    try { payload=await response.json(); }
    catch(e) { throw new Error('Respons Apps Script tidak dapat dibaca. Pastikan Web App telah di-deploy dengan akses Anyone.'); }
    if(!payload || payload.ok!==true) throw new Error(payload&&payload.error?payload.error:'Permintaan tidak berhasil.');
    if(payload.version && payload.version!=='1.7.18') throw new Error('Versi backend '+payload.version+' tidak cocok. Diperlukan 1.7.18.');
    return payload.data;
  };
  function loading(on){$('loading').classList.toggle('hidden',!on)}
  function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+(type==='error'?'error':'success');el.textContent=msg;$('toastRoot').appendChild(el);setTimeout(()=>el.remove(),3800)}
  function showAuth(){ document.body.classList.add('auth-mode');$('appShell').classList.add('hidden');$('authScreen').classList.remove('hidden'); }
  function showApp(){ document.body.classList.remove('auth-mode');$('authScreen').classList.add('hidden');$('appShell').classList.remove('hidden'); }
  async function init(){
    loading(true);
    try{
      const initData=await call('getAppInit');state.init=initData;
      if(!initData.installed){showAuth();renderAuth('notInstalled');return;}
      if(initData.needsAdmin){showAuth();renderAuth('createAdmin');return;}
      const saved=sessionStorage.getItem('nt_token');
      if(saved){try{const d=await call('getDashboardData',saved);state.token=saved;state.user=d.user;state.data=d;showApp();buildNav();renderPage();loadProfilePhotoOnce();if(state.user.forcePasswordChange)openPasswordModal(true);return;}catch(e){sessionStorage.removeItem('nt_token');}}
      showAuth();renderAuth('login');
    }catch(e){showAuth();renderAuth('error',e.message);}
    finally{loading(false);}
  }
  function renderAuth(mode,message=''){
    const card=$('authCard');
    if(mode==='notInstalled'){
      card.innerHTML=`<h2>Instalasi belum selesai</h2><p>Database NEDUKA TASK belum disiapkan. Jalankan fungsi <b>setupNedukaTask()</b> satu kali dari editor Apps Script.</p><div class="notice warning">Setelah fungsi selesai, deploy ulang Web App lalu muat kembali alamat aplikasi.</div>`;return;
    }
    if(mode==='error') {card.innerHTML=`<h2>Aplikasi belum siap</h2><p>${esc(message)}</p><button class="btn btn-primary" style="width:100%" onclick="init()">Coba lagi</button>`;return;}
    if(mode==='createAdmin'){
      card.innerHTML=`<h2>Buat akun administrator</h2><p>Ini adalah akun pengelola pertama NEDUKA TASK. Pembuatan akun dilindungi kode aktivasi satu kali dari pengelola Apps Script.</p><div class="notice warning" style="margin-bottom:13px">Minta kode aktivasi kepada pemilik proyek. Kode berlaku 30 menit dan hanya dapat digunakan satu kali.</div><form class="auth-form" onsubmit="submitInitialAdmin(event)"><div class="field"><label>Kode aktivasi administrator</label><input name="setupCode" required autocomplete="one-time-code" autocapitalize="characters" placeholder="Tempel kode dari Apps Script"></div><div class="field"><label>Nama lengkap</label><input name="fullName" required minlength="3" placeholder="Nama administrator"></div><div class="field"><label>Username admin</label><input name="username" required minlength="4" autocomplete="username" placeholder="contoh: admin.neduka"></div><div class="field"><label>Kata sandi</label><input name="password" type="password" required minlength="8" autocomplete="new-password" placeholder="Minimal 8 karakter"></div><div class="field"><label>Ulangi kata sandi</label><input name="confirm" type="password" required minlength="8" autocomplete="new-password"></div><button class="btn btn-primary" type="submit">Buat akun admin</button></form><div class="auth-switch">Kode aktivasi dihapus otomatis setelah akun pertama berhasil dibuat.</div>`;return;
    }
    if(mode==='register'){
      loadRegisterOptions().then(opts=>{
        card.innerHTML=`<h2>Daftar akun siswa</h2><p>Gunakan NISN sesuai data sekolah. Akun langsung aktif setelah pendaftaran berhasil.</p><form class="auth-form" onsubmit="submitRegister(event)"><div class="field"><label>Nama lengkap</label><input name="fullName" required minlength="3"></div><div class="field"><label>NISN (angka sesuai data sekolah)</label><input name="nisn" type="text" inputmode="numeric" pattern="[0-9]+" oninput="this.value=this.value.replace(/[^0-9]/g,'')" required></div><div class="field"><label>Kelas</label><select name="classId"><option value="">Pilih kelas (opsional)</option>${opts.classes.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}${c.year?' · '+esc(c.year):''}</option>`).join('')}</select></div><div class="field"><label>Periode akademik</label><select name="periodId"><option value="">Pilih periode (opsional)</option>${opts.periods.map(p=>`<option value="${esc(p.id)}">${esc(p.year)} · Semester ${esc(p.semester)}</option>`).join('')}</select></div><div class="field"><label>Email (opsional)</label><input name="email" type="email"></div><div class="field"><label>Nomor HP (opsional)</label><input name="phone" inputmode="tel"></div><div class="field"><label>Kata sandi</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>Ulangi kata sandi</label><input name="confirm" type="password" minlength="8" required></div><button class="btn btn-primary" type="submit">Kirim pendaftaran</button></form><div class="auth-switch"><button class="link-btn" onclick="renderAuth('login')">Kembali ke halaman masuk</button></div>`;
      }).catch(e=>toast(e.message,'error'));return;
    }
    card.innerHTML=`<h2>Selamat datang kembali</h2><p>Masuk untuk melanjutkan aktivitas belajar dan pengelolaan tugas.</p><form class="auth-form" onsubmit="submitLogin(event)"><div class="field"><label>Username / NISN</label><input name="username" required autocomplete="username" placeholder="Masukkan username atau NISN"></div><div class="field"><label>Kata sandi</label><input name="password" type="password" required autocomplete="current-password" placeholder="Masukkan kata sandi"></div><button class="btn btn-primary" type="submit">Masuk ke NEDUKA TASK</button></form><div class="auth-switch">Siswa belum memiliki akun? <button class="link-btn" onclick="renderAuth('register')">Daftar di sini</button></div>`;
  }
  async function loadRegisterOptions(){return await call('getPublicRegistrationOptions')}
  async function submitInitialAdmin(e){e.preventDefault();const f=new FormData(e.target);if(f.get('password')!==f.get('confirm'))return toast('Konfirmasi kata sandi tidak sama.','error');loading(true);try{const r=await call('createInitialAdmin',{setupCode:f.get('setupCode'),fullName:f.get('fullName'),username:f.get('username'),password:f.get('password')});toast(r.message);renderAuth('login');}catch(err){toast(err.message,'error');}finally{loading(false)}}
  async function submitLogin(e){e.preventDefault();const f=new FormData(e.target);loading(true);try{const r=await call('login',f.get('username'),f.get('password'));state.token=r.token;sessionStorage.setItem('nt_token',r.token);state.user=r.user;state.data=await call('getDashboardData',state.token);state.photoRequested=false;showApp();buildNav();renderPage();loadProfilePhotoOnce();if(r.user.forcePasswordChange)openPasswordModal(true);}catch(err){toast(err.message,'error');}finally{loading(false)}}
  async function submitRegister(e){e.preventDefault();const f=new FormData(e.target);if(f.get('password')!==f.get('confirm'))return toast('Konfirmasi kata sandi tidak sama.','error');loading(true);try{const d={fullName:f.get('fullName'),nisn:f.get('nisn'),classId:f.get('classId'),periodId:f.get('periodId'),email:f.get('email'),phone:f.get('phone'),password:f.get('password')};const r=await call('registerStudent',d);toast(r.message);renderAuth('login');}catch(err){const msg=String(err&&err.message||err);if(msg.toLowerCase().includes('sudah terdaftar')||msg.toLowerCase().includes('sudah memiliki akun')){renderAuth('login');toast(msg+' Silakan masuk, bukan mendaftar ulang.','error');}else{toast(msg,'error');}}finally{loading(false)}}
  async function logoutApp(){loading(true);try{await call('logout',state.token);}catch(e){}state.token='';state.user=null;state.data=null;state.profilePhoto='';state.photoRequested=false;sessionStorage.removeItem('nt_token');state.page='home';showAuth();renderAuth('login');loading(false)}
  function buildNav(){
    const teacher=['ADMIN','GURU'].includes(state.user.role);
    const items=teacher?[['home','⌂','Ringkasan'],['students','♙','Data Siswa'],['tasks','▤','Tugas'],['assessment','▧','Penilaian'],['messages','✉','Pesan'],['classes','▦','Data Kelas'],['periods','◷','Periode'],...(state.user.role==='ADMIN'?[['teachers','♧','Guru']]:[]),['profile','◎','Profil']]:[['home','⌂','Beranda'],['report','▧','Rekap Nilai'],['messages','✉','Pesan'],['profile','◎','Profil']];
    $('navMenu').innerHTML=items.map(([id,ico,label])=>`<button type="button" data-page="${id}" aria-label="${label}" class="${state.page===id?'active':''}" onclick="goPage('${id}')"><span class="ico" aria-hidden="true">${ico}</span><span class="nav-text">${label}</span></button>`).join('');
    $('topName').textContent=state.user.fullName||state.user.username;$('topRole').textContent=roleLabel(state.user.role);if(!state.profilePhoto)$('topAvatar').textContent=initials(state.user.fullName||state.user.username);$('sidebarVersion').textContent='Versi '+state.init.version;
  }
  function roleLabel(r){return r==='ADMIN'?'Administrator':r==='GURU'?'Guru':'Siswa'}
  function initials(v){return String(v||'N').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'N'}
  function goPage(p){state.page=p;state.activeSubjectId='';state.search='';state.filter='ALL';state.classFilter='ALL';state.pageNo=1;buildNav();renderPage()}
  function openSubject(id){const subject=(state.data.subjects||[]).find(x=>x.id===id);if(!subject)return toast('Mata pelajaran tidak ditemukan.','error');state.activeSubjectId=id;state.page='subject';renderPage()}
  async function refreshData(){state.data=await call('getDashboardData',state.token);buildNav();renderPage()}
  function renderPage(){
    const activeSubject=(state.data.subjects||[]).find(x=>x.id===state.activeSubjectId);
    const names={home:state.user.role==='SISWA'?'Beranda':'Ringkasan',students:'Data Siswa',classes:'Data Kelas',periods:'Periode Akademik',teachers:'Data Guru',profile:'Profil Saya',tasks:'Manajemen Tugas',assessment:'Penilaian Akademik',report:'Rekap Nilai Anda',messages:'Pesan Akademik',subject:activeSubject?activeSubject.name:'Ruang Mata Pelajaran'};
    $('topTitle').textContent=names[state.page]||'NEDUKA TASK';
    if(state.page==='home')renderHome();else if(state.page==='subject')renderSubjectWorkspace();else if(state.page==='students')renderStudents();else if(state.page==='tasks')renderTasks();else if(state.page==='assessment')renderAssessment();else if(state.page==='report')renderStudentReport();else if(state.page==='messages')renderMessages();else if(state.page==='classes')renderClasses();else if(state.page==='periods')renderPeriods();else if(state.page==='teachers')renderTeachers();else renderProfile();
  }
  function renderSubjectWorkspace(){
    const subject=(state.data.subjects||[]).find(x=>x.id===state.activeSubjectId);
    if(!subject){state.page='home';renderHome();return;}
    const s=state.data.student||{};
    const cls=(state.data.classes||[]).find(x=>x.id===s.classId);
    const period=(state.data.periods||[]).find(x=>x.id===s.periodId);
    const isInf=subject.code==='INF';
    $('pageContent').innerHTML=`<div class="page-head"><div><h1>Ruang ${esc(subject.name)}</h1><p>${isInf?'Ruang belajar Informatika dan keterampilan digital.':'Ruang belajar komunikasi dan literasi Bahasa Inggris.'}</p></div><button class="btn btn-light" onclick="goPage('home')">← Kembali ke beranda</button></div><section class="subject-workspace-hero ${isInf?'subject-purple':'subject-blue'}"><div class="subject-symbol">${isInf?'⌘':'A'}</div><div><span class="subject-code">${esc(subject.code||'MATA PELAJARAN')}</span><h2>${esc(subject.name)}</h2><p>${isInf?'Belajar konsep, berpikir komputasional, pemecahan masalah, dan keterampilan digital.':'Belajar vocabulary, grammar, reading, writing, dan speaking.'}</p></div></section><div class="subject-workspace-grid"><section class="panel"><span class="eyebrow-label">IDENTITAS PEMBELAJARAN</span><h3>Informasi kelas</h3><div class="student-facts"><div><small>Nama siswa</small><b>${esc(s.name||state.user.fullName)}</b></div><div><small>Kelas</small><b>${esc(cls?cls.name:'Belum ditentukan')}</b></div><div><small>Periode</small><b>${esc(period?period.year+' · Semester '+period.semester:'Belum ditentukan')}</b></div></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow-label">RUANG BELAJAR</span><h3>Daftar tugas</h3></div>${['ADMIN','GURU'].includes(state.user.role)?`<button class="btn btn-primary btn-small" onclick="openTaskModal('', '${subject.id}')">＋ Buat tugas</button>`:''}</div><div id="subjectTaskList"><div class="empty">Memuat tugas...</div></div></section></div>`;
    loadSubjectTasks(subject.id);
  }
  async function loadSubjectTasks(subjectId){try{const tasks=await call('getTasks',state.token,subjectId);const box=$('subjectTaskList');if(!box)return;if(!tasks.length){box.innerHTML='<div class=\"empty\">Belum ada tugas untuk mata pelajaran ini.</div>';return;}const pageSize=5,total=Math.max(1,Math.ceil(tasks.length/pageSize));state.taskPageNo=Math.min(state.taskPageNo,total);const page=tasks.slice((state.taskPageNo-1)*pageSize,state.taskPageNo*pageSize);box.innerHTML=page.map(t=>`<article class=\"task-item\"><div class=\"task-item-head\"><div><b>${esc(t.title)}</b><small>${esc(t.className||'')} · ${esc(t.periodName||'')}</small></div><span class=\"badge ${t.submission?'badge-active':'badge-pending'}\">${t.submission?'Sudah dikumpulkan':(t.status==='PUBLISHED'?'Tugas tersedia':esc(t.status))}</span></div><p>${esc(t.description||'Tidak ada petunjuk tambahan.')}</p>${t.resourceUrl?`<span class=\"muted\">${esc(t.resourceName||'Bahan tugas tersedia')}</span>`:''}<div class=\"task-item-foot\"><span>Batas: ${esc(t.dueAt||'Tidak ditentukan')}</span><div class=\"row-actions\">${state.user.role==='SISWA'?`${t.submission?`<button class=\"btn btn-light btn-small\" onclick=\"showMyTaskHistory('${t.id}')\">Riwayat pengumpulan</button>`:''}<button class=\"btn btn-primary btn-small\" onclick=\"openSubmitTask('${t.id}','${esc(t.assessmentCategory||'')}')\">${['TUGAS','LAINNYA'].includes(String(t.assessmentCategory||'').toUpperCase())?'Kirim dan Ajukan Verifikasi':(t.submission?'Kirim ulang bukti':'Kirim Bukti')}</button>`:`<button class=\"btn btn-light btn-small\" onclick=\"showTaskSubmissions('${t.id}')\">${Number(t.submissionStudentCount||0)} dari ${Number(t.targetStudentCount||0)} siswa mengumpulkan</button>`}</div></div></article>`).join('')+`<div class=\"pagination\"><span>Halaman ${state.taskPageNo} dari ${total} · ${tasks.length} tugas</span><div class=\"pager-actions\"><button class=\"btn btn-light btn-small\" ${state.taskPageNo<=1?'disabled':''} onclick=\"changeTaskPage(-1)\">Sebelumnya</button><button class=\"btn btn-light btn-small\" ${state.taskPageNo>=total?'disabled':''} onclick=\"changeTaskPage(1)\">Berikutnya</button></div></div>`;}catch(e){const box=$('subjectTaskList');if(box)box.innerHTML=`<div class=\"empty\">${esc(e.message)}</div>`;}}
  function changeTaskPage(delta){state.taskPageNo=Math.max(1,state.taskPageNo+delta);loadSubjectTasks(state.activeSubjectId)}

  async function renderTasks(){const subjectOptions=(state.data.subjects||[]).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join(''),classOptions=(state.data.classes||[]).filter(c=>String(c.status||'').trim().toUpperCase()==='ACTIVE').map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join(''),periodOptions=(state.data.periods||[]).filter(p=>String(p.status||'').trim().toUpperCase()==='ACTIVE').map(p=>`<option value="${p.id}">${esc(p.year)} · Semester ${esc(p.semester)}</option>`).join('');$('pageContent').innerHTML=`<div class="page-head"><div><h1>Manajemen Tugas</h1><p>Buat dan kelola tugas berdasarkan mata pelajaran, kelas, dan periode akademik.</p></div><button class="btn btn-primary" onclick="openTaskModal()">＋ Buat tugas</button></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Daftar tugas</div><div class="panel-desc">Gunakan filter untuk menemukan tugas dengan cepat.</div></div><button class="btn btn-outline btn-small" onclick="resetTaskFilters()">Reset filter</button></div><div class="task-filter-grid"><input class="input" id="taskSearchFilter" placeholder="Cari judul tugas..." oninput="applyTaskFilters()"><select class="input" id="taskSubjectFilter" onchange="applyTaskFilters()"><option value="">Semua mata pelajaran</option>${subjectOptions}</select><select class="input" id="taskClassFilter" onchange="applyTaskFilters()"><option value="">Semua kelas</option>${classOptions}<option value="__GRADE7">Seluruh tingkat 7</option><option value="__GRADE8">Seluruh tingkat 8</option><option value="__GRADE9">Seluruh tingkat 9</option></select><select class="input" id="taskPeriodFilter" onchange="applyTaskFilters()"><option value="">Semua periode</option>${periodOptions}</select><select class="input" id="taskStatusFilter" onchange="applyTaskFilters()"><option value="">Semua status</option><option value="PUBLISHED">Published</option><option value="DRAFT">Draft</option><option value="CLOSED">Closed</option></select><select class="input" id="taskTypeFilter" onchange="applyTaskFilters()"><option value="">Semua jenis tugas</option><option value="TUGAS">Tugas</option><option value="PROYEK">Proyek</option><option value="LATIHAN">Latihan</option></select><select class="input" id="taskDueFilter" onchange="applyTaskFilters()"><option value="">Semua tenggat</option><option value="UPCOMING">Belum melewati batas</option><option value="OVERDUE">Terlambat</option><option value="NO_DUE">Tanpa batas waktu</option></select></div><div id="taskFilterCount" class="panel-desc" style="margin:10px 0"></div><div id="taskTable"><div class="empty">Memuat daftar tugas...</div></div></div>`;await loadTaskPage();}
  async function loadTaskPage(){try{const list=await call('getTasks',state.token,'');window.__ntTaskCache=list;applyTaskFilters();}catch(e){const box=$('taskTable');if(box)box.innerHTML=`<div class="empty">${esc(e.message)}</div>`;}}
  function resetTaskFilters(){['taskSearchFilter','taskSubjectFilter','taskClassFilter','taskPeriodFilter','taskStatusFilter','taskTypeFilter','taskDueFilter'].forEach(id=>{const el=$(id);if(el)el.value='';});applyTaskFilters();}
  function applyTaskFilters(){const all=window.__ntTaskCache||[],val=id=>$(id)?.value||'',q=val('taskSearchFilter').trim().toLowerCase(),subject=val('taskSubjectFilter'),cls=val('taskClassFilter'),period=val('taskPeriodFilter'),status=val('taskStatusFilter'),type=val('taskTypeFilter'),due=val('taskDueFilter'),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta'}).format(new Date());let list=all.filter(t=>{if(subject&&t.subjectId!==subject)return false;if(period&&t.periodId!==period)return false;if(status&&t.status!==status)return false;if(type&&t.taskType!==type)return false;if(q&&!String(t.title||'').toLowerCase().includes(q))return false;if(cls){if(cls.startsWith('__GRADE')){if(!(t.targetType==='GRADE'&&String(t.targetGrade)===cls.slice(7)))return false;}else if(!(t.targetType==='CLASS'&&t.classId===cls))return false;}const deadline=String(t.dueAt||'').slice(0,10);if(due==='NO_DUE'&&deadline)return false;if(due==='UPCOMING'&&(!deadline||deadline<today))return false;if(due==='OVERDUE'&&(!deadline||deadline>=today||t.status!=='PUBLISHED'))return false;return true;});const box=$('taskTable'),count=$('taskFilterCount');if(count)count.textContent=`Menampilkan ${list.length} dari ${all.length} tugas`;if(!box)return;if(!list.length){box.innerHTML='<div class="empty">Tidak ada tugas yang sesuai dengan filter.</div>';return;}box.innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Judul tugas</th><th>Mata pelajaran</th><th>Kelas</th><th>Periode</th><th>Batas</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${list.map(t=>`<tr><td><b>${esc(t.title)}</b><small class="muted" style="display:block">${esc(t.description||'')}</small></td><td>${esc(t.subjectName)}</td><td>${esc(t.className)}</td><td>${esc(t.periodName||'-')}</td><td>${esc(t.dueAt||'-')}</td><td>${esc(t.status)}</td><td><div class="row-actions"><button class="btn btn-light btn-small" onclick="openTaskModal('${t.id}')">Edit</button><button class="btn btn-danger btn-small" onclick="archiveTask('${t.id}')">Hapus</button></div></td></tr>`).join('')}</tbody></table></div>`;}
  function openTaskModal(id='',subjectId=''){const t=window.__ntTaskCache?.find(x=>x.id===id)||{};const subjects=state.data.subjects||[],classes=state.data.classes||[],periods=state.data.periods||[];openModal(id?'Edit tugas':'Buat tugas',`<form onsubmit="submitTaskForm(event,'${id}')"><div class="field"><label>Judul tugas</label><input name="title" required minlength="3" value="${esc(t.title||'')}"></div><div class="field" style="margin-top:10px"><label>Petunjuk / deskripsi</label><textarea name="description" rows="3">${esc(t.description||'')}</textarea></div><div class="form-grid" style="margin-top:10px"><div class="field"><label>Mata pelajaran</label><select name="subjectId" required>${optionEmpty(subjects.length?'Pilih mata pelajaran':'Tidak ada mata pelajaran aktif')}${subjects.map(s=>`<option value="${esc(s.id)}" ${(t.subjectId||subjectId)===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Tujuan kelas</label><select name="target" required>${classes.filter(c=>String(c.status||'').trim().toUpperCase()==='ACTIVE').map((c,i)=>`<option value="CLASS:${c.id}" ${(t.targetType==='CLASS'&&t.classId===c.id)||(!t.targetType&&!t.classId&&i===0)?'selected':''}>${esc(c.name)}</option>`).join('')}<option value="GRADE:9" ${t.targetType==='GRADE'&&t.targetGrade==='9'?'selected':''}>Seluruh kelas 9</option><option value="GRADE:8" ${t.targetType==='GRADE'&&t.targetGrade==='8'?'selected':''}>Seluruh kelas 8</option><option value="GRADE:7" ${t.targetType==='GRADE'&&t.targetGrade==='7'?'selected':''}>Seluruh kelas 7</option><option value="ALL:" ${t.targetType==='ALL'?'selected':''}>Semua kelas 7, 8, dan 9</option></select></div><div class="field"><label>Periode akademik</label><select name="periodId"><option value="">Ikuti kelas</option>${periods.filter(p=>String(p.status||'').trim().toUpperCase()==='ACTIVE').map(p=>`<option value="${p.id}" ${t.periodId===p.id?'selected':''}>${esc(p.year)} · Semester ${esc(p.semester)}</option>`).join('')}</select></div><div class="field"><label>Jenis tugas</label><select name="taskType"><option ${t.taskType==='TUGAS'?'selected':''}>TUGAS</option><option ${t.taskType==='PROYEK'?'selected':''}>PROYEK</option><option ${t.taskType==='LATIHAN'?'selected':''}>LATIHAN</option></select></div><div class="field"><label>Hubungkan dengan komponen nilai</label><select name="assessmentCategory"><option value="">Tidak dihubungkan</option><option value="TUGAS" ${t.assessmentCategory==='TUGAS'?'selected':''}>Tugas / PR (siswa dapat mengajukan nilai)</option><option value="LAINNYA" ${t.assessmentCategory==='LAINNYA'?'selected':''}>Lainnya (siswa dapat mengajukan nilai)</option><option value="PRAKTIK" ${t.assessmentCategory==='PRAKTIK'?'selected':''}>Praktik (nilai diinput guru)</option><option value="PAS/PAT" ${t.assessmentCategory==='PAS/PAT'?'selected':''}>PAS/PAT (nilai diinput guru)</option></select><small class="muted">Jika dipilih, komponen nilai dibuat otomatis sesuai kelas sasaran dan periode.</small></div><div class="field"><label>Bobot penilaian (%)</label><input name="assessmentWeight" type="number" min="1" max="100" value="${Number(t.assessmentWeight||20)}"></div><div class="field"><label>Model pengerjaan</label><select name="workMode"><option value="INDIVIDUAL">Individu</option><option value="GROUP" ${t.workMode==='GROUP'?'selected':''}>Kelompok</option></select></div><div class="field"><label>Mulai</label><input name="openAt" type="datetime-local" value="${esc((t.openAt||'').replace(' ','T').slice(0,16))}"></div><div class="field"><label>Batas pengumpulan</label><input name="dueAt" type="datetime-local" value="${esc((t.dueAt||'').replace(' ','T').slice(0,16))}"></div><div class="field span-2"><label>Link bahan / referensi (opsional)</label><input name="resourceUrl" type="url" value="${esc(t.resourceUrl||'')}" placeholder="https://..."></div><div class="field span-2"><label>Nama bahan (opsional)</label><input name="resourceName" value="${esc(t.resourceName||'')}"></div></div><div class="modal-actions"><button type="button" class="btn btn-outline" onclick="closeModal()">Batal</button><button class="btn btn-primary">Simpan tugas</button></div></form>`);}
  async function submitTaskForm(e,id){e.preventDefault();const f=new FormData(e.target);if(!f.get('subjectId')||!f.get('target'))return toast('Pilih mata pelajaran dan sasaran kelas terlebih dahulu.','error');const target=String(f.get('target')||'').split(':');const d={id,title:f.get('title'),description:f.get('description'),subjectId:f.get('subjectId'),targetType:target[0]||'CLASS',targetGrade:target[0]==='GRADE'?target[1]:'',classId:target[0]==='CLASS'?target[1]:'',periodId:f.get('periodId'),taskType:f.get('taskType'),assessmentCategory:f.get('assessmentCategory'),assessmentWeight:f.get('assessmentWeight'),maxScore:100,workMode:f.get('workMode'),openAt:String(f.get('openAt')||'').replace('T',' '),dueAt:String(f.get('dueAt')||'').replace('T',' '),resourceUrl:f.get('resourceUrl'),resourceName:f.get('resourceName'),status:'PUBLISHED'};loading(true);try{const r=await call('saveTask',state.token,d);closeModal();toast(r.message);if(state.page==='tasks')loadTaskPage();else if(state.page==='subject')loadSubjectTasks(state.activeSubjectId);}catch(err){toast(err.message,'error')}finally{loading(false)}}
  async function archiveTask(id){if(!confirm('Hapus tugas dari daftar aktif? Riwayat pengumpulan dan nilai siswa tetap disimpan.'))return;try{const r=await call('deleteTask',state.token,id);toast(r.message);if(state.page==='tasks')loadTaskPage();else loadSubjectTasks(state.activeSubjectId);}catch(e){toast(e.message,'error')}}
  async function openSubmitTask(taskId,category=''){
    const canRequest=['TUGAS','LAINNYA'].includes(String(category).toUpperCase());
    openModal(canRequest?'Kirim tugas dan ajukan nilai':'Kirim bukti tugas',`<form onsubmit="submitStudentTask(event,'${taskId}',${canRequest})"><div class="field"><label>Jawaban / keterangan pekerjaan</label><textarea name="answer" rows="3" placeholder="Tuliskan jawaban atau keterangan pekerjaan (opsional jika melampirkan bukti)..."></textarea></div><div class="field" style="margin-top:10px"><label>Bukti fisik (foto / PDF / Word, maksimal 5 berkas; 5 MB per berkas)</label><input name="proofFiles" type="file" multiple accept="image/jpeg,image/png,image/webp,.pdf,.doc,.docx"></div><div class="field" style="margin-top:10px"><label>Tautan video (Google Drive / YouTube)</label><textarea name="videoLinks" rows="2" placeholder="Tempel tautan video Drive atau YouTube"></textarea></div>${canRequest?`<div class="field" style="margin-top:10px"><label>Nilai yang diajukan</label><input name="requestedScore" type="number" min="0" max="100" step="0.01" required placeholder="Masukkan nilai sesuai hasil pekerjaan"><small class="muted">Nilai baru masuk rekap setelah diverifikasi guru.</small></div>`:`<div class="notice" style="margin-top:10px">Tugas ini dinilai langsung oleh guru. Siswa cukup mengirim jawaban dan bukti; tidak ada input nilai mandiri.</div>`}<div class="notice" style="margin-top:10px">Foto dikompres otomatis. Dokumen disimpan di Google Drive. Video gunakan tautan Drive/YouTube yang dapat diakses guru.</div><div class="modal-actions"><button type="button" class="btn btn-outline" onclick="closeModal()">Batal</button><button class="btn btn-primary">${canRequest?'Kirim dan Ajukan Verifikasi':'Kirim Bukti'}</button></div></form>`);
  }
  function fileAsData(file){return new Promise((resolve,reject)=>{const rd=new FileReader();rd.onerror=()=>reject(new Error('Berkas tidak dapat dibaca: '+file.name));rd.onload=()=>resolve(String(rd.result));rd.readAsDataURL(file);});}
  async function prepareProofFile(file){if(file.type.startsWith('image/')){const data=await compressImage(file);return {name:file.name.replace(/\.[^.]+$/,'')+'.jpg',mimeType:'image/jpeg',data};}if(file.size>5*1024*1024)throw new Error('Dokumen '+file.name+' melebihi 5 MB.');return {name:file.name,mimeType:file.type||'application/octet-stream',data:await fileAsData(file)};}
  async function submitStudentTask(e,taskId,canRequest=false){e.preventDefault();const f=new FormData(e.target),files=[...(e.target.elements.proofFiles.files||[])],links=String(f.get('videoLinks')||'').trim(),answer=[String(f.get('answer')||'').trim(),links].filter(Boolean).join('\nVideo: ');if(!answer&&!files.length)return toast('Isi jawaban atau lampirkan bukti pekerjaan.','error');if(files.length>5)return toast('Maksimal 5 berkas.','error');if(links){const urls=links.split(/\s+/).filter(Boolean);if(urls.some(u=>!/^https?:\/\//i.test(u)||!/(drive\.google\.com|youtu\.be|youtube\.com)/i.test(u)))return toast('Tautan video harus berasal dari Google Drive atau YouTube.','error');}const score=canRequest?String(f.get('requestedScore')||'').trim():'';if(canRequest&&score==='')return toast('Masukkan nilai yang diajukan.','error');loading(true);try{const prepared=[];for(const file of files)prepared.push(await prepareProofFile(file));const payload={taskId,answer,files:prepared};if(canRequest)payload.score=score;const r=await call('submitTask',state.token,payload);closeModal();toast(canRequest?'Bukti dan pengajuan nilai berhasil dikirim. Menunggu verifikasi guru.':r.message);loadSubjectTasks(state.activeSubjectId);}catch(err){toast(err.message,'error')}finally{loading(false)}}
  function openNestedPreviewModal(title,body){state.modalBackHtml=$('modalRoot').innerHTML;openModal(title,`${body}<div class="modal-actions"><button class="btn btn-outline" onclick="returnToSubmissionList()">Kembali ke daftar bukti</button></div>`);}
  function returnToSubmissionList(){if(state.modalBackHtml){$('modalRoot').innerHTML=state.modalBackHtml;state.modalBackHtml=null;}else closeModal();}
  async function getProofData(fileId){
    const key=String(fileId||'');
    if(!key)throw new Error('ID berkas bukti tidak tersedia.');
    if(state.proofDataCache[key])return state.proofDataCache[key];
    const result=await call('getSubmissionFileData',state.token,key);
    if(!result||!result.data)throw new Error('Isi berkas bukti kosong atau tidak dapat dibaca.');
    state.proofDataCache[key]=result;return result;
  }
  async function loadSubmissionThumbnails(){
    const nodes=[...document.querySelectorAll('#modalRoot .proof-image[data-file-id]')];
    for(const node of nodes){
      if(node.dataset.loaded==='1'||node.dataset.loading==='1')continue;
      node.dataset.loading='1';
      try{
        const result=await getProofData(node.dataset.fileId);
        const mime=result.mimeType||node.dataset.mime||'image/jpeg';
        if(!mime.startsWith('image/'))throw new Error('Berkas bukan gambar.');
        const src=`data:${mime};base64,${result.data}`;
        node.innerHTML=`<img src="${src}" alt="${esc(node.dataset.name||'Bukti siswa')}" loading="lazy"><span class="proof-image-caption">${esc(node.dataset.name||'Foto bukti')}</span>`;
        node.dataset.loaded='1';
      }catch(e){node.innerHTML=`<span class="proof-image-error">Gambar tidak dapat dimuat</span><small>${esc(node.dataset.name||'Bukti')}</small>`;node.dataset.loaded='1';}
      finally{delete node.dataset.loading;}
    }
  }
  async function previewSubmissionFile(fileId,mime,name){
    loading(true);
    try{
      const result=await getProofData(fileId);
      const dataUrl=`data:${result.mimeType||mime};base64,${result.data}`;
      let body='';
      if((result.mimeType||mime||'').startsWith('image/')){
        body=`<div class="proof-large-frame"><img src="${dataUrl}" alt="${esc(name)}"></div>`;
      }else if((result.mimeType||mime)==='application/pdf'){
        body=`<iframe src="${dataUrl}" title="${esc(name)}" style="width:100%;height:65dvh;border:0;border-radius:10px"></iframe>`;
      }else{
        body=`<div class="notice">Pratinjau Word langsung tidak didukung di semua browser. Bapak/Ibu dapat mengunduh berkas ini.</div><a class="btn btn-primary" href="${dataUrl}" download="${esc(name)}">Unduh ${esc(name)}</a>`;
      }
      openNestedPreviewModal('Pratinjau bukti: '+esc(name),body);
    }catch(e){toast(e.message||'Bukti tidak dapat dibuka.','error')}
    finally{loading(false)}
  }
  async function showTaskSubmissions(taskId,initialFilter='submitted'){state.modalBackHtml=null;state.activeSubmissionTaskId=taskId;state.submissionStatusFilter=initialFilter;loading(true);try{state.submissionData=await call('getTaskSubmissions',state.token,taskId);state.submissionPageNo=1;renderTaskSubmissionPage();}catch(e){toast(e.message,'error')}finally{loading(false)}}
  async function showStudentProofMatrix(focusStudentId=''){
    const f=state.assessmentFilters.verify||assessmentDefaultFilters();
    if(!f.subjectId||!f.classId||!f.periodId)return toast('Pilih mata pelajaran, kelas, dan periode terlebih dahulu.','error');
    loading(true);
    try{
      const [taskRows]=await Promise.all([call('getTasks',state.token,f.subjectId)]);
      const cls=(state.data.classes||[]).find(c=>String(c.id)===String(f.classId));
      const grade=String(cls?.gradeLevel||cls?.grade||cls?.name||'').replace(/[^0-9]/g,'');
      const tasks=(taskRows||[]).filter(t=>String(t.periodId||'')===String(f.periodId)&&(
        String(t.classId||'')===String(f.classId)||
        (String(t.targetType||'').toUpperCase()==='GRADE'&&grade&&String(t.targetGrade||'')===grade)||
        String(t.targetType||'').toUpperCase()==='ALL'));
      if(!tasks.length){openModal('Bukti tugas per siswa','<div class="empty">Belum ada tugas pada mata pelajaran, kelas, dan periode ini.</div>');return;}
      const results=await Promise.all(tasks.map(async task=>({task,data:await call('getTaskSubmissions',state.token,task.id)})));
      const studentMap=new Map();
      results.forEach(({task,data})=>(data.students||[]).forEach(st=>{
        const id=String(st.studentId||st.id||'');if(!id)return;
        if(!studentMap.has(id))studentMap.set(id,{id,name:st.studentName||st.name||'-',nisn:st.nisn||'',className:st.className||'',items:{}});
        studentMap.get(id).items[task.id]=st;
      }));
      let students=[...studentMap.values()].sort((a,b)=>a.name.localeCompare(b.name,'id'));
      // Jika tombol Bukti diklik dari pengajuan tertentu, modal hanya memuat siswa pemilik pengajuan itu.
      if(focusStudentId) students=students.filter(x=>String(x.id)===String(focusStudentId));
      state.proofMatrix={tasks,students,focusStudentId:String(focusStudentId||'')};
      state.proofMatrixPage=1;renderStudentProofMatrix();
    }catch(e){toast(e.message||'Bukti tugas gagal dimuat.','error');}
    finally{loading(false);}
  }
  function renderStudentProofMatrix(){
    const matrix=state.proofMatrix||{tasks:[],students:[]},students=matrix.students||[],tasks=matrix.tasks||[],size=6,total=Math.max(1,Math.ceil(students.length/size));
    state.proofMatrixPage=Math.min(Math.max(1,state.proofMatrixPage||1),total);
    const page=students.slice((state.proofMatrixPage-1)*size,state.proofMatrixPage*size);
    const cards=page.map(st=>{
      const buttons=tasks.map(t=>{const row=st.items[t.id],done=!!(row&&row.submitted),count=Number(row?.submissionCount||0);return `<button class="proof-task-chip ${done?'is-done':'is-missing'}" ${done?`onclick="openStudentTaskProof('${esc(t.id)}','${esc(st.id)}')"`:'disabled'} title="${done?'Lihat '+count+' bukti':'Belum mengumpulkan'}"><span>${esc(t.title||'Tugas')}</span><b>${done?`Bukti ${count}`:'Belum'}</b></button>`}).join('');
      const completed=tasks.filter(t=>st.items[t.id]?.submitted).length;
      return `<article class="proof-matrix-student"><div class="proof-matrix-student-head"><div><b>${esc(st.name)}</b><small>NISN ${esc(st.nisn||'-')} · ${esc(st.className||'-')}</small></div><span class="badge ${completed===tasks.length?'badge-active':'badge-pending'}">${completed}/${tasks.length} tugas</span></div><div class="proof-matrix-task-grid">${buttons}</div></article>`;
    }).join('')||'<div class="empty">Tidak ada siswa pada kelas ini.</div>';
    const completed=students.filter(st=>tasks.some(t=>st.items[t.id]?.submitted)).length;
    const focused=!!matrix.focusStudentId;
    openModal(focused&&students[0]?`Bukti tugas · ${esc(students[0].name)}`:'Bukti tugas per siswa',`<div class="submission-summary"><b>${focused&&students[0]?esc(students[0].name):`${students.length} siswa`} · ${tasks.length} tugas</b><span>${focused?'Hanya bukti milik siswa ini yang ditampilkan.':'Pilih siswa dan tugas untuk melihat bukti masing-masing.'} Tombol aktif dapat dibuka; tombol abu-abu berarti belum mengumpulkan.</span></div><div class="proof-matrix-task-legend"><span><i class="status-dot done"></i>Sudah mengumpulkan</span><span><i class="status-dot pending"></i>Belum mengumpulkan</span></div><div class="proof-matrix-list">${cards}</div>${focused?'':`<div class="pagination"><span>Halaman ${state.proofMatrixPage} dari ${total} · ${students.length} siswa</span><div class="pager-actions"><button class="btn btn-light btn-small" ${state.proofMatrixPage<=1?'disabled':''} onclick="changeProofMatrixPage(-1)">Sebelumnya</button><button class="btn btn-light btn-small" ${state.proofMatrixPage>=total?'disabled':''} onclick="changeProofMatrixPage(1)">Selanjutnya</button></div></div>`}`);
  }
  function changeProofMatrixPage(delta){state.proofMatrixPage=Math.max(1,(state.proofMatrixPage||1)+delta);renderStudentProofMatrix();}
  function openStudentTaskProof(taskId,studentId){
    const matrix=state.proofMatrix||{},task=(matrix.tasks||[]).find(t=>String(t.id)===String(taskId)),student=(matrix.students||[]).find(st=>String(st.id)===String(studentId)),row=student?.items?.[taskId];
    if(!task||!student||!row||!row.submitted)return;
    const history=row.submissions||[];
    const pending=(state.assessmentRequestsByTab.verify||[]).filter(r=>String(r.studentId||r.student_id||'')===String(studentId)&&String(r.taskId||'')===String(taskId));
    const request=pending.find(r=>!['APPROVED','REJECTED'].includes(String(r.status||'').toUpperCase()))||pending[0];
    const historyHtml=history.map(r=>`<section class="submission-attempt"><div class="task-item-head"><div><b>Pengiriman ke-${r.attempt}</b><small>${esc(r.submittedAt||'')}</small></div><span class="badge badge-active">${esc(r.status||'SUBMITTED')}</span></div>${r.answer?`<p>${esc(r.answer)}</p>`:''}${videoPreviewButtons(r.answer)}${(r.files||[]).length?`<div class="proof-grid">${r.files.map(x=>String(x.mimeType||'').startsWith('image/')?`<button type="button" class="proof-image" data-file-id="${esc(x.fileId)}" data-mime="${esc(x.mimeType)}" data-name="${esc(x.name)}" onclick="previewSubmissionFile('${esc(x.fileId)}','${esc(x.mimeType)}','${esc(x.name)}')"><span class="proof-image-loading">Memuat foto…</span></button>`:`<button type="button" class="proof-preview-btn" onclick="previewSubmissionFile('${esc(x.fileId)}','${esc(x.mimeType)}','${esc(x.name)}')"><span>📎</span><b>${esc(x.name)}</b><small>Lihat dokumen</small></button>`).join('')}</div>`:'<div class="empty">Tidak ada lampiran pada pengiriman ini.</div>'}</section>`).join('');
    const review=request?`<div class="proof-review-bar"><div><b>Nilai diajukan: ${esc(request.score??'-')}</b><small>Keputusan hanya berlaku untuk pengajuan tugas ini.</small></div><div class="row-actions"><button class="btn btn-primary" onclick="reviewScoreRequest('${esc(request.id)}','APPROVED')">✓ Setujui</button><button class="btn btn-danger" onclick="reviewScoreRequest('${esc(request.id)}','REJECTED')">✕ Tolak</button></div></div>`:'<div class="notice">Tidak ada pengajuan nilai yang menunggu verifikasi untuk tugas ini.</div>';
    openNestedPreviewModal(`${esc(student.name)} · ${esc(task.title)}`,`<div class="proof-student-task-head"><b>${esc(student.name)}</b><small>${esc(task.title)} · ${esc(student.className||'')}</small></div>${historyHtml||'<div class="empty">Riwayat bukti tidak ditemukan.</div>'}${review}`);loadSubmissionThumbnails();
  }
  function renderTaskSubmissionPage(){const data=state.submissionData||{students:[],summary:{}},allStudents=data.students||[],students=allStudents.filter(st=>state.submissionStatusFilter==='all'||(state.submissionStatusFilter==='submitted'?!!st.submitted:!st.submitted)),size=5,total=Math.max(1,Math.ceil(students.length/size)),page=students.slice((state.submissionPageNo-1)*size,state.submissionPageNo*size);const html=page.map(st=>{const history=st.submissions||[];const historyHtml=history.map(r=>`<div class="submission-attempt"><div class="task-item-head"><div><b>Pengiriman ke-${r.attempt}</b><small>${esc(r.submittedAt||'')}</small></div><span class="badge badge-active">${esc(r.status)}</span></div>${r.answer?`<p>${esc(r.answer)}</p>`:''}${videoPreviewButtons(r.answer)}${(r.files||[]).length?`<div class="proof-grid">${(r.files||[]).map(x=>{const imageFile=String(x.mimeType||'').startsWith('image/');return imageFile?`<button type="button" class="proof-image" data-file-id="${esc(x.fileId)}" data-mime="${esc(x.mimeType)}" data-name="${esc(x.name)}" onclick="previewSubmissionFile('${esc(x.fileId)}','${esc(x.mimeType)}','${esc(x.name)}')"><span class="proof-image-loading">Memuat foto…</span></button>`:`<button type="button" class="proof-preview-btn" onclick="previewSubmissionFile('${esc(x.fileId)}','${esc(x.mimeType)}','${esc(x.name)}')"><span>${x.mimeType==='application/pdf'?'📕':'📎'}</span><b>${esc(x.name)}</b><small>${x.mimeType==='application/pdf'?'Lihat PDF':'Unduh dokumen'}</small></button>`}).join('')}</div>`:''}</div>`).join('');return `<section class="panel submission-history-card ${st.submitted?'is-submitted':'is-not-submitted'}"><div class="task-item-head"><div><b>${esc(st.studentName)}</b><small>NISN ${esc(st.nisn||'-')} · ${esc(st.className||'-')}</small></div><span class="badge ${st.submitted?'badge-active':'badge-pending'}">${st.submitted?`${st.submissionCount} pengiriman`:'Belum mengumpulkan'}</span></div>${historyHtml||'<div class="empty">Siswa ini belum mengumpulkan tugas.</div>'}</section>`}).join('')||'<div class="empty">Belum ada siswa pada sasaran tugas ini.</div>';const sum=data.summary||{};openModal('Bukti pengumpulan siswa',`<div class="submission-summary"><b>${sum.submittedStudents||0} dari ${sum.totalStudents||0} siswa sudah mengumpulkan</b><span>${sum.notSubmittedStudents||0} belum mengumpulkan · ${sum.totalSubmissions||0} total pengiriman</span><div class="submission-status-legend"><span><i class="status-dot done"></i>Sudah mengumpulkan</span><span><i class="status-dot pending"></i>Belum mengumpulkan</span></div></div><div class="submission-status-filter"><button class="btn ${state.submissionStatusFilter==='submitted'?'btn-primary':'btn-light'} btn-small" onclick="setSubmissionStatusFilter('submitted')">Sudah mengumpulkan (${sum.submittedStudents||0})</button><button class="btn ${state.submissionStatusFilter==='pending'?'btn-primary':'btn-light'} btn-small" onclick="setSubmissionStatusFilter('pending')">Belum mengumpulkan (${sum.notSubmittedStudents||0})</button><button class="btn ${state.submissionStatusFilter==='all'?'btn-primary':'btn-light'} btn-small" onclick="setSubmissionStatusFilter('all')">Semua siswa</button></div><div class="submission-student-list">${html}</div><div class="pagination"><span>Halaman ${state.submissionPageNo} dari ${total} · ${students.length} siswa</span><div class="pager-actions"><button class="btn btn-light btn-small" ${state.submissionPageNo<=1?'disabled':''} onclick="changeSubmissionPage(-1)">Sebelumnya</button><button class="btn btn-light btn-small" ${state.submissionPageNo>=total?'disabled':''} onclick="changeSubmissionPage(1)">Berikutnya</button></div></div>`);loadSubmissionThumbnails()}
  function setSubmissionStatusFilter(filter){state.submissionStatusFilter=filter;state.submissionPageNo=1;renderTaskSubmissionPage()}
  function changeSubmissionPage(delta){state.submissionPageNo=Math.max(1,state.submissionPageNo+delta);renderTaskSubmissionPage()}
  async function showMyTaskHistory(taskId){state.modalBackHtml=null;loading(true);try{state.mySubmissionRows=await call('getMyTaskSubmissionHistory',state.token,taskId);state.mySubmissionPageNo=1;renderMyTaskHistoryPage();}catch(e){toast(e.message,'error')}finally{loading(false)}}
  function renderMyTaskHistoryPage(){const rows=state.mySubmissionRows||[],size=5,total=Math.max(1,Math.ceil(rows.length/size)),page=rows.slice((state.mySubmissionPageNo-1)*size,state.mySubmissionPageNo*size);const html=page.map(r=>`<section class=\"panel submission-history-card\"><div class=\"task-item-head\"><div><b>Pengiriman ke-${r.attempt}</b><small>${esc(r.submittedAt||'')}</small></div><span class=\"badge badge-active\">${esc(r.status)}</span></div><p>${esc(r.answer||'Tanpa keterangan')}</p>${videoPreviewButtons(r.answer)}<div class=\"proof-grid\">${r.files.map(x=>`<button type=\"button\" class=\"proof-preview-btn\" onclick=\"previewSubmissionFile('${esc(x.fileId)}','${esc(x.mimeType)}','${esc(x.name)}')\"><span>📎</span><b>${esc(x.name)}</b><small>Lihat bukti</small></button>`).join('')}</div></section>`).join('')||'<div class=\"empty\">Belum ada riwayat pengumpulan.</div>';openModal('Riwayat pengumpulan saya',`${html}<div class=\"pagination\"><span>Halaman ${state.mySubmissionPageNo} dari ${total} · ${rows.length} catatan</span><div class=\"pager-actions\"><button class=\"btn btn-light btn-small\" ${state.mySubmissionPageNo<=1?'disabled':''} onclick=\"changeMySubmissionPage(-1)\">Sebelumnya</button><button class=\"btn btn-light btn-small\" ${state.mySubmissionPageNo>=total?'disabled':''} onclick=\"changeMySubmissionPage(1)\">Berikutnya</button></div></div>`)}
  function changeMySubmissionPage(delta){state.mySubmissionPageNo=Math.max(1,state.mySubmissionPageNo+delta);renderMyTaskHistoryPage()}
  function videoPreviewButtons(answer){const urls=String(answer||'').match(/https?:\/\/[^\s]+/g)||[];return urls.filter(u=>/(drive\.google\.com|youtu\.be|youtube\.com)/i.test(u)).map(u=>`<button class=\"btn btn-light btn-small\" type=\"button\" onclick=\"previewTaskVideo('${esc(u)}')\">▶ Lihat video</button>`).join('')}
  function previewTaskVideo(url){let src='';const yt=url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([A-Za-z0-9_-]{6,})/i);if(yt)src='https://www.youtube-nocookie.com/embed/'+yt[1];else{const id=url.match(/[-\w]{25,}/);if(id)src='https://drive.google.com/file/d/'+id[0]+'/preview'}if(!src)return toast('Tautan video tidak dapat dikenali.','error');openNestedPreviewModal('Pratinjau video',`<iframe src=\"${src}\" class=\"modal-preview-frame\" allow=\"autoplay; encrypted-media; picture-in-picture\" allowfullscreen></iframe>`)}


  function assessmentDefaultFilters(){
    const subjects=activeRows(state.data.subjects),classes=activeRows(state.data.classes),periods=activeRows(state.data.periods);
    return {subjectId:subjects[0]?.id||'',classId:classes[0]?.id||'',periodId:periods.find(p=>String(p.status||'').toUpperCase()==='ACTIVE')?.id||periods[0]?.id||''};
  }
  function assessmentFilterMarkup(tab){
    const f=state.assessmentFilters[tab]||assessmentDefaultFilters();state.assessmentFilters[tab]=f;
    const subjects=activeRows(state.data.subjects),classes=activeRows(state.data.classes),periods=activeRows(state.data.periods);
    return `<div class="assessment-scope-filters"><label><span>Mata pelajaran</span><select class="input" onchange="assessmentScopeChange('${tab}','subjectId',this.value)">${subjects.map(x=>`<option value="${esc(x.id)}" ${String(f.subjectId)===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label><span>Kelas</span><select class="input" onchange="assessmentScopeChange('${tab}','classId',this.value)">${classes.map(x=>`<option value="${esc(x.id)}" ${String(f.classId)===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label><span>Periode</span><select class="input" onchange="assessmentScopeChange('${tab}','periodId',this.value)">${periods.map(x=>`<option value="${esc(x.id)}" ${String(f.periodId)===String(x.id)?'selected':''}>${esc(x.year)} · Semester ${esc(x.semester)}</option>`).join('')}</select></label></div>`;
  }
  async function renderAssessment(){
    if(state.user.role==='SISWA'){goPage('report');return;}
    const subjects=activeRows(state.data.subjects),classes=activeRows(state.data.classes),periods=activeRows(state.data.periods);
    const empty=!subjects.length?'Belum ada mata pelajaran aktif atau penugasan mapel untuk akun ini.':!classes.length?'Belum ada kelas aktif.':!periods.length?'Belum ada periode akademik aktif.':'';
    $('pageContent').innerHTML=`<div class="page-head"><div><h1>Penilaian Akademik</h1><p>Kelola verifikasi, rekap, dan input nilai dalam satu ruang kerja.</p></div><button class="btn btn-primary" onclick="openAssessmentColumn()" ${empty?'disabled':''}>＋ Tambah komponen nilai</button></div><div class="panel assessment-main-panel"><div id="assessmentTable">${empty?`<div class="empty">${empty}</div>`:'Memuat data penilaian...'}</div></div>`;
    if(!empty){for(const tab of ['verify','table','entry','missing'])state.assessmentFilters[tab]=state.assessmentFilters[tab]||assessmentDefaultFilters();await loadAssessment(state.assessmentTab||'verify');}
  }
  async function loadAssessment(tab=state.assessmentTab||'verify'){
    const box=$('assessmentTable');if(!box)return;const seq=(state.assessmentLoadSeq[tab]||0)+1;state.assessmentLoadSeq[tab]=seq;const f=state.assessmentFilters[tab]||assessmentDefaultFilters();state.assessmentFilters[tab]=f;
    if(!f.subjectId||!f.classId||!f.periodId){box.innerHTML='<div class="empty">Pilih mata pelajaran, kelas, dan periode.</div>';return;}
    box.innerHTML='<div class="empty">Memuat data penilaian...</div>';
    try{const [d,requests]=await Promise.all([call('getAssessmentData',state.token,{subjectId:f.subjectId,classId:f.classId,periodId:f.periodId}),call('getScoreRequests',state.token,{subjectId:f.subjectId,classId:f.classId,periodId:f.periodId})]);if(state.assessmentLoadSeq[tab]!==seq)return;state.assessmentByTab[tab]=d||{columns:[],students:[]};state.assessmentRequestsByTab[tab]=requests||[];if(tab===state.assessmentTab){state.assessment=state.assessmentByTab[tab];state.assessmentRequests=state.assessmentRequestsByTab[tab];renderAssessmentTable();}}
    catch(e){if($('assessmentTable'))box.innerHTML=`<div class="empty">Data penilaian gagal dimuat: ${esc(e.message)}</div>`;}
  }
  function assessmentTab(tab){state.assessmentTab=tab; if(tab==='missing'){renderAssessmentTable();loadMissingTasks();return;} const d=state.assessmentByTab[tab];if(d){state.assessment=d;state.assessmentRequests=state.assessmentRequestsByTab[tab]||[];renderAssessmentTable();}else{renderAssessmentTable();loadAssessment(tab);}}
  function assessmentScopeChange(tab,key,value){state.assessmentFilters[tab]=state.assessmentFilters[tab]||assessmentDefaultFilters();state.assessmentFilters[tab][key]=value;state.assessmentPages[tab]=1;if(tab==='missing'){loadMissingTasks();return;}delete state.assessmentByTab[tab];loadAssessment(tab);}
  function assessmentFilter(key,value){state.assessmentQueries[key]=value;state.assessmentPages[key]=1;renderAssessmentTable()}
  function assessmentComponentFilter(key,value){state.assessmentComponentFilter[key]=value;state.assessmentPages[key]=1;renderAssessmentTable()}
  function assessmentPage(key,delta){state.assessmentPages[key]=Math.max(1,(state.assessmentPages[key]||1)+delta);renderAssessmentTable()}
  async function loadMissingTasks(){const box=$('assessmentTable');if(!box)return;const f=state.assessmentFilters.missing||assessmentDefaultFilters();box.innerHTML='<div class="empty">Memuat daftar tugas...</div>';try{const rows=await call('getTasks',state.token,f.subjectId||'');const cls=(state.data.classes||[]).find(c=>String(c.id)===String(f.classId));const grade=String(cls?.gradeLevel||cls?.grade||cls?.name||'').replace(/[^0-9]/g,'');state.missingTasks=(rows||[]).filter(t=>String(t.periodId||'')===String(f.periodId||'')&&(String(t.classId||'')===String(f.classId||'')||(String(t.targetType||'').toUpperCase()==='GRADE'&&grade&&String(t.targetGrade||'')===grade)));renderAssessmentTable();}catch(e){box.innerHTML=`<div class="empty">Daftar tugas gagal dimuat: ${esc(e.message)}</div>`}}
  function missingTaskSearch(value){state.missingQuery=value;renderAssessmentTable()}
  function assessmentPager(key,page,total,count,size){return `<div class="pagination"><span>Halaman ${page} dari ${total} · ${count} data</span><div class="pager-actions"><button class="btn btn-light btn-small" ${page<=1?'disabled':''} onclick="assessmentPage('${key}',-1)">Sebelumnya</button><button class="btn btn-light btn-small" ${page>=total?'disabled':''} onclick="assessmentPage('${key}',1)">Selanjutnya</button></div></div>`}
  function renderAssessmentTable(){
    const box=$('assessmentTable');if(!box)return;const tab=state.assessmentTab||'verify';const d=state.assessmentByTab[tab]||{columns:[],students:[]};const requests=state.assessmentRequestsByTab[tab]||[];const cols=d.columns||[],students=d.students||[],sortedStudents=sortStudentsAlphabetically(students);
    const nav=`<div class="assessment-tabs"><button class="assessment-tab ${tab==='verify'?'active':''}" onclick="assessmentTab('verify')">Verifikasi <span>${(state.assessmentRequestsByTab.verify||[]).length}</span></button><button class="assessment-tab ${tab==='missing'?'active':''}" onclick="assessmentTab('missing')">Siswa belum mengumpulkan</button><button class="assessment-tab ${tab==='table'?'active':''}" onclick="assessmentTab('table')">Rekap nilai <span>${(state.assessmentByTab.table?.students||[]).length}</span></button><button class="assessment-tab ${tab==='entry'?'active':''}" onclick="assessmentTab('entry')">Input nilai</button></div>`;
    let body='',scope=assessmentFilterMarkup(tab);
    if(tab==='missing'){const tasks=state.missingTasks||[];body=`<section class="assessment-segment"><div class="assessment-segment-head"><div><b>Daftar tugas dan siswa yang belum mengumpulkan</b><small>Pilih tugas untuk melihat siswa yang belum mengirimkan bukti.</small></div><input class="input assessment-search" placeholder="Cari judul tugas..." value="${esc(state.missingQuery||'')}" oninput="missingTaskSearch(this.value)"></div>${tasks.length?`<div class="table-wrap assessment-list-table"><table class="data-table"><thead><tr><th>Tugas</th><th>Kelas sasaran</th><th>Periode</th><th>Pengumpulan</th><th>Aksi</th></tr></thead><tbody>${tasks.filter(t=>String(t.title||'').toLowerCase().includes(String(state.missingQuery||'').toLowerCase())).map(t=>`<tr><td><b>${esc(t.title)}</b><small class="muted" style="display:block">${esc(t.subjectName||'')}</small></td><td>${esc(t.className||t.targetGrade||'-')}</td><td>${esc(t.periodName||'-')}</td><td>${Number(t.submissionStudentCount||0)} / ${Number(t.targetStudentCount||0)} siswa</td><td><button class="btn btn-light btn-small" onclick="showTaskSubmissions('${t.id}','pending')">Lihat siswa belum mengumpulkan</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Tidak ada tugas pada kombinasi filter ini.</div>'}</section>`;}else if(tab==='verify'){ 
      const q=(state.assessmentQueries.verify||'').toLowerCase();
      const pendingByStudent=new Map();
      requests.forEach(r=>{const sid=String(r.studentId||r.student_id||'');if(!sid)return;if(!pendingByStudent.has(sid))pendingByStudent.set(sid,[]);pendingByStudent.get(sid).push(r)});
      // Daftar utama memakai roster kelas: satu nama siswa hanya tampil satu kali.
      const roster=students.map(st=>({id:String(st.id||st.studentId||''),name:st.name||st.studentName||'-',nisn:st.nisn||'',className:st.className||'',items:pendingByStudent.get(String(st.id||st.studentId||''))||[]}))
        .filter(st=>st.id&&`${st.name} ${st.nisn}`.toLowerCase().includes(q))
        .sort((a,b)=>a.name.localeCompare(b.name,'id'));
      const size=10,total=Math.max(1,Math.ceil(roster.length/size)),page=Math.min(state.assessmentPages.verify||1,total);state.assessmentPages.verify=page;const rows=roster.slice((page-1)*size,page*size);
      body=`<section class="assessment-segment"><div class="assessment-segment-head"><div><b>Daftar siswa kelas</b><small>${roster.length} siswa · urut alfabet A–Z · ${requests.length} pengajuan menunggu verifikasi.</small></div><input class="input assessment-search" placeholder="Cari nama siswa..." value="${esc(state.assessmentQueries.verify||'')}" oninput="assessmentFilter('verify',this.value)"></div>${rows.length?`<div class="table-wrap assessment-list-table"><table class="data-table verify-student-table"><thead><tr><th style="width:54px">No</th><th>Nama siswa</th><th>Status pengajuan</th><th>Aksi</th></tr></thead><tbody>${rows.map((st,i)=>`<tr><td>${(page-1)*size+i+1}</td><td><b>${esc(st.name)}</b><small class="muted" style="display:block">NISN ${esc(st.nisn||'-')}</small></td><td>${st.items.length?`<span class="badge badge-pending">${st.items.length} menunggu verifikasi</span>`:'<span class="muted">Belum ada pengajuan</span>'}</td><td><button class="btn btn-light btn-small" onclick="showStudentProofMatrix('${esc(st.id)}')">▧ Bukti</button></td></tr>`).join('')}</tbody></table></div>${assessmentPager('verify',page,total,roster.length,size)}`:'<div class="empty">Tidak ada siswa yang cocok dengan pencarian.</div>'}</section>`;
    }else if(tab==='table'){
      const q=(state.assessmentQueries.table||'').toLowerCase(),cf=state.assessmentComponentFilter.table||'ALL';const filtered=sortedStudents.filter(st=>`${st.name||''} ${st.nisn||''}`.toLowerCase().includes(q));const visibleCols=cf==='ALL'?cols:cols.filter(c=>c.id===cf);const size=10,total=Math.max(1,Math.ceil(filtered.length/size)),page=Math.min(state.assessmentPages.table||1,total);state.assessmentPages.table=page;const rows=filtered.slice((page-1)*size,page*size);
      body=`<section class="assessment-segment"><div class="assessment-segment-head"><div><b>Daftar nilai siswa</b><small>${students.length} siswa · ${cols.length} komponen penilaian.</small></div><div class="assessment-filter-row"><input class="input assessment-search" placeholder="Cari nama / NISN..." value="${esc(state.assessmentQueries.table||'')}" oninput="assessmentFilter('table',this.value)"><select class="input assessment-select" onchange="assessmentComponentFilter('table',this.value)"><option value="ALL">Semua komponen</option>${cols.map(c=>`<option value="${esc(c.id)}" ${cf===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>${cols.length?`<div class="table-wrap assessment-score-table"><table class="data-table"><thead><tr><th>Nama siswa</th>${visibleCols.map(c=>`<th>${esc(c.name)}<small class="muted" style="display:block">${esc(c.category)} · ${c.weight}%</small></th>`).join('')}<th>Rata-rata</th><th>Rank</th></tr></thead><tbody>${rows.map(st=>`<tr><td><b>${esc(st.name)}</b><small class="muted" style="display:block">${esc(st.nisn)}</small></td>${visibleCols.map(c=>{const v=(st.scores||[]).find(x=>x.columnId===c.id)||{};return `<td>${v.score===null||v.score===undefined?'<span class="muted">—</span>':v.score}</td>`}).join('')}<td><b>${st.average===null?'—':st.average}</b></td><td>${st.rank||'—'}</td></tr>`).join('')}</tbody></table></div>${assessmentPager('table',page,total,filtered.length,size)}`:'<div class="empty">Belum ada komponen nilai untuk kombinasi ini.</div>'}</section>`;
    }else{
      const q=(state.assessmentQueries.entry||'').toLowerCase(),cf=state.assessmentComponentFilter.entry||'ALL';const filtered=sortedStudents.filter(st=>`${st.name||''} ${st.nisn||''}`.toLowerCase().includes(q));const editableCols=cols.filter(c=>c.scoreMode!=='GROUP_SAME'&&(cf==='ALL'||c.id===cf));const size=10,total=Math.max(1,Math.ceil(filtered.length/size)),page=Math.min(state.assessmentPages.entry||1,total);state.assessmentPages.entry=page;const rows=filtered.slice((page-1)*size,page*size);
      body=`<section class="assessment-segment"><div class="assessment-segment-head"><div><b>Input dan koreksi nilai</b><small>Pilih nama siswa untuk membuka formulir nilai.</small></div><div class="assessment-filter-row"><input class="input assessment-search" placeholder="Cari nama / NISN..." value="${esc(state.assessmentQueries.entry||'')}" oninput="assessmentFilter('entry',this.value)"><select class="input assessment-select" onchange="assessmentComponentFilter('entry',this.value)"><option value="ALL">Semua komponen</option>${cols.map(c=>`<option value="${esc(c.id)}" ${cf===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>${rows.length?`<div class="assessment-entry-grid">${rows.map(st=>`<details class="score-entry"><summary>${esc(st.name)} <span>${esc(st.className||'')}</span></summary>${editableCols.map(c=>{const v=(st.scores||[]).find(x=>x.columnId===c.id)||{};return `<form class="score-form" onsubmit="saveScore(event,'${c.id}','${st.id}')"><label>${esc(c.name)} (${c.maxScore})${c.scoreMode==='GROUP_DIFFERENT'?' · Nilai kelompok per individu':''}</label>${c.scoreMode==='GROUP_DIFFERENT'?'<input name="groupLabel" class="input" placeholder="Nama kelompok" style="margin:6px 0">':''}<div class="score-form-row"><input name="score" class="input" type="number" min="0" max="${c.maxScore}" step="0.01" value="${v.score===null||v.score===undefined?'':v.score}" required><button class="btn btn-light btn-small">Simpan</button></div></form>`}).join('')||'<small class="muted">Tidak ada komponen input individu.</small>'}</details>`).join('')}</div>${assessmentPager('entry',page,total,filtered.length,size)}`:'<div class="empty">Tidak ada siswa yang cocok dengan pencarian.</div>'}${cols.filter(c=>c.scoreMode==='GROUP_SAME'&&(cf==='ALL'||c.id===cf)).map(c=>`<details class="assessment-group-box"><summary>Input nilai kelompok: ${esc(c.name)}</summary><p class="panel-desc">Pilih minimal dua anggota kelompok. Nilai diberikan sama kepada semua anggota terpilih.</p><form class="score-form" onsubmit="saveGroupScore(event,'${c.id}')"><div class="field"><label>Nama kelompok</label><input name="groupLabel" required placeholder="Contoh: Kelompok 1"></div><div class="group-member-grid assessment-group-members">${sortedStudents.map(st=>`<label class="check-row"><input type="checkbox" name="studentIds" value="${st.id}"> ${esc(st.name)}</label>`).join('')}</div><div class="score-form-row"><input name="score" class="input" type="number" min="0" max="${c.maxScore}" step="0.01" placeholder="Nilai kelompok" required><button class="btn btn-primary btn-small">Simpan nilai kelompok</button></div></form></details>`).join('')}</section>`;
    }
    box.innerHTML=`${nav}${scope}${body}`;
  }
  function openAssessmentColumn(){const subjects=activeRows(state.data.subjects),classes=activeRows(state.data.classes),periods=activeRows(state.data.periods);if(!subjects.length||!classes.length||!periods.length)return toast('Komponen belum dapat dibuat. Pastikan tersedia mata pelajaran, kelas, dan periode yang aktif.', 'error');openModal('Tambah komponen penilaian',`<form onsubmit="submitAssessmentColumn(event)"><div class="field"><label>Nama komponen</label><input name="name" required placeholder="Contoh: Tugas/PR 1"></div><div class="form-grid" style="margin-top:10px"><div class="field"><label>Kategori</label><select name="category" id="assessmentCategory" onchange="toggleAssessmentMode()"><option value="TUGAS">Tugas/PR</option><option value="PRAKTIK">Praktik</option><option value="PAS/PAT">PAS/PAT</option><option value="LAINNYA">Lainnya</option></select></div><div class="field"><label>Model penilaian praktik</label><select name="scoreMode" id="assessmentScoreMode" disabled><option value="INDIVIDUAL">Mandiri / individu</option><option value="GROUP_SAME">Kelompok — nilai sama</option><option value="GROUP_DIFFERENT">Kelompok — nilai berbeda per siswa</option></select><small class="muted">Pilihan kelompok hanya berlaku untuk kategori Praktik.</small></div><div class="field"><label>Bobot (%)</label><input name="weight" type="number" min="1" max="100" value="20" required></div><div class="field"><label>Mata pelajaran</label><select name="subjectId" required>${optionEmpty('Pilih mata pelajaran')}${subjects.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Kelas</label><select name="classId" required>${optionEmpty('Pilih kelas')}${classes.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Periode</label><select name="periodId" required>${optionEmpty('Pilih periode')}${periods.map(p=>`<option value="${esc(p.id)}">${esc(p.year)} · Semester ${esc(p.semester)}</option>`).join('')||''}</select></div><div class="field"><label>Nilai maksimum</label><input name="maxScore" type="number" min="1" value="100" required></div></div><div class="modal-actions"><button type="button" class="btn btn-outline" onclick="closeModal()">Batal</button><button class="btn btn-primary">Simpan komponen</button></div></form>`)}
  function toggleAssessmentMode(){const c=$('assessmentCategory'),m=$('assessmentScoreMode');if(!c||!m)return;const enabled=c.value==='PRAKTIK';m.disabled=!enabled;if(!enabled)m.value='INDIVIDUAL';}
  async function submitAssessmentColumn(e){e.preventDefault();const f=new FormData(e.target);if(!f.get('subjectId')||!f.get('classId')||!f.get('periodId'))return toast('Pilih mata pelajaran, kelas, dan periode terlebih dahulu.','error');loading(true);try{const r=await call('saveAssessmentColumn',state.token,{name:f.get('name'),category:f.get('category'),weight:f.get('weight'),subjectId:f.get('subjectId'),classId:f.get('classId'),periodId:f.get('periodId'),maxScore:f.get('maxScore'),scoreMode:f.get('scoreMode')||'INDIVIDUAL'});const savedSubject=String(f.get('subjectId')),savedClass=String(f.get('classId')),savedPeriod=String(f.get('periodId'));closeModal();toast(r.message);const tab=state.assessmentTab||'verify';state.assessmentFilters[tab]={subjectId:savedSubject,classId:savedClass,periodId:savedPeriod};delete state.assessmentByTab[tab];await loadAssessment(tab)}catch(err){toast(err.message,'error')}finally{loading(false)}}
  async function reviewScoreRequest(requestId,decision){loading(true);try{const r=await call('reviewStudentScoreRequest',state.token,{requestId,decision});closeModal();toast(r.message);['entry','table'].forEach(tab=>{delete state.assessmentByTab[tab];delete state.assessmentRequestsByTab[tab];});delete state.assessmentByTab[state.assessmentTab];delete state.assessmentRequestsByTab[state.assessmentTab];await loadAssessment(state.assessmentTab)}catch(e){toast(e.message,'error')}finally{loading(false)}}
  async function saveGroupScore(e,columnId){e.preventDefault();const f=new FormData(e.target),studentIds=f.getAll('studentIds');loading(true);try{const r=await call('saveAssessmentGroupScore',state.token,{columnId,studentIds,groupLabel:f.get('groupLabel'),score:f.get('score')});toast(r.message);delete state.assessmentByTab[state.assessmentTab];await loadAssessment(state.assessmentTab)}catch(err){toast(err.message,'error')}finally{loading(false)}}
  async function saveScore(e,columnId,studentId){e.preventDefault();const f=new FormData(e.target);loading(true);try{const r=await call('saveAssessmentScore',state.token,{columnId,studentId,score:f.get('score'),groupLabel:f.get('groupLabel')||''});toast(r.message);delete state.assessmentByTab[state.assessmentTab];await loadAssessment(state.assessmentTab)}catch(err){toast(err.message,'error')}finally{loading(false)}}
  async function renderStudentReport(){const subjects=state.data.subjects||[],periods=state.data.periods||[];$('pageContent').innerHTML=`<div class="page-head"><div><h1>Rekap Nilai Anda</h1><p>Halaman ini hanya untuk melihat nilai yang telah diverifikasi guru.</p></div></div><div class="toolbar report-filters"><select class="input filter" id="reportSubject" onchange="loadStudentReport()"><option value="">Semua mata pelajaran</option>${subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><select class="input filter" id="reportPeriod" onchange="loadStudentReport()"><option value="">Semua periode</option>${periods.map(p=>`<option value="${esc(p.id)}">${esc(p.year)} · Semester ${esc(p.semester)}</option>`).join('')||''}</select></div><div id="studentReportBox"><div class="empty">Memuat rekap nilai...</div></div>`;await loadStudentReport()}
  async function loadStudentReport(){try{const d=await call('getStudentReport',state.token,'',$('reportSubject')?.value||'',$('reportPeriod')?.value||'');const r=d.report,box=$('studentReportBox');if(!box)return;if(!r){box.innerHTML='<div class="empty">Belum ada nilai yang dapat ditampilkan.</div>';return;}box.innerHTML=`<div class="stats report-stats"><article class="stat-card"><div class="stat-label">Rata-rata nilai</div><div class="stat-value">${r.average===null?'—':r.average}</div></article><article class="stat-card"><div class="stat-label">Ranking</div><div class="stat-value">${r.rank||'—'}</div></article><article class="stat-card"><div class="stat-label">Predikat</div><div class="stat-value" style="font-size:20px">${esc(r.predicate)}</div></article></div><section class="panel"><div class="panel-title">${esc(d.student.name)}</div><div class="panel-desc">NISN ${esc(d.student.nisn)}</div><div class="table-wrap" style="margin-top:14px"><table class="data-table"><thead><tr><th>Komponen penilaian</th><th>Kategori</th><th>Bobot</th><th>Nilai</th></tr></thead><tbody>${d.columns.map((c,i)=>`<tr><td>${esc(c.name)}</td><td>${esc(c.category)}</td><td>${c.weight}%</td><td>${r.scores[i]?.score??'—'}</td></tr>`).join('')}</tbody></table></div><p class="panel-desc" style="margin-top:10px">Nilai yang masih menunggu verifikasi belum ditampilkan sebagai nilai akhir.</p></section>`;}catch(e){const b=$('studentReportBox');if(b)b.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
  async function renderMessages(){
    $('pageContent').innerHTML=`<div class="page-head"><div><h1>Pesan Akademik</h1><p>Komunikasi antara guru dan siswa. Riwayat dikelompokkan per bulan dan tahun.</p></div><button class="btn btn-primary" onclick="openMessageModal()">＋ Tulis pesan</button></div><div class="panel"><div class="toolbar"><button class="btn btn-outline btn-small" onclick="changeMessageMonth(-1)">← Sebelumnya</button><strong id="messageMonthLabel">Memuat...</strong><button class="btn btn-outline btn-small" onclick="changeMessageMonth(1)">Selanjutnya →</button></div><div id="messageList"><div class="empty">Memuat pesan...</div></div></div>`;
    try{state.messageRows=await call('getAcademicMessages',state.token);if(!state.messageMonth){const d=new Date();state.messageMonth={year:d.getFullYear(),month:d.getMonth()};}renderMessageMonth();}catch(e){$('messageList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}
  }
  function renderMessageMonth(){const rows=state.messageRows||[],{year,month}=state.messageMonth;const label=new Date(year,month,1).toLocaleDateString('id-ID',{month:'long',year:'numeric'});$('messageMonthLabel').textContent=label;const list=rows.filter(m=>{const d=new Date(String(m.createdAt||'').replace(' ','T'));return !isNaN(d)&&d.getFullYear()===year&&d.getMonth()===month});$('messageList').innerHTML=list.length?list.map(m=>`<article class="task-item"><div class="task-item-head"><b>${esc(m.subject)}</b><small>${esc(m.senderName)} → ${esc(m.recipientName||'Penerima')}</small></div><p>${esc(m.body)}</p><div class="task-item-foot"><span>${esc(m.createdAt||'')} · ${m.isRead?'Sudah dibaca':(m.senderId===state.user.userId?'Menunggu dibaca':'Belum dibaca')}</span><div class="row-actions">${m.senderId!==state.user.userId&&!m.isRead?`<button class="btn btn-light btn-small" onclick="markMessageRead('${m.id}')">Tandai dibaca</button>`:''}${m.senderId!==state.user.userId?`<button class="btn btn-light btn-small" onclick="replyMessage('${m.senderId}','${esc(m.subject).replace(/'/g,"\\'")}')">Tanggapi</button>`:''}${m.canEdit?`<button class="btn btn-light btn-small" onclick="editMessage('${m.id}')">Edit</button>`:''}${m.canDelete?`<button class="btn btn-danger btn-small" onclick="deleteMessage('${m.id}')">Hapus</button>`:''}</div></div></article>`).join(''):'<div class="empty">Tidak ada pesan pada bulan ini.</div>'}
  function changeMessageMonth(delta){const d=new Date(state.messageMonth.year,state.messageMonth.month+delta,1);state.messageMonth={year:d.getFullYear(),month:d.getMonth()};renderMessageMonth()}
  async function markMessageRead(id){try{const r=await call('markAcademicMessageRead',state.token,id);toast(r.message);await renderMessages()}catch(e){toast(e.message,'error')}}
  async function deleteMessage(id){if(!confirm('Hapus pesan ini dari kotak pesan?'))return;try{const r=await call('deleteAcademicMessage',state.token,id);toast(r.message);await renderMessages()}catch(e){toast(e.message,'error')}}
  async function editMessage(id){const m=(state.messageRows||[]).find(x=>x.id===id);if(!m)return;openModal('Edit pesan',`<form onsubmit="submitEditMessage(event,'${id}')"><div class="field"><label>Judul</label><input name="subject" required value="${esc(m.subject)}"></div><div class="field" style="margin-top:10px"><label>Isi pesan</label><textarea name="body" rows="5" required>${esc(m.body)}</textarea></div><div class="modal-actions"><button type="button" class="btn btn-outline" onclick="closeModal()">Batal</button><button class="btn btn-primary">Simpan perubahan</button></div></form>`)}
  async function submitEditMessage(e,id){e.preventDefault();const f=new FormData(e.target);try{const r=await call('editAcademicMessage',state.token,{id,subject:f.get('subject'),body:f.get('body')});closeModal();toast(r.message);await renderMessages()}catch(err){toast(err.message,'error')}}
  async function replyMessage(recipientId,subject){const rec=await call('getAcademicRecipients',state.token);const r=rec.find(x=>x.id===recipientId);if(!r)return toast('Penerima tidak tersedia.','error');openModal('Tanggapi pesan',`<form onsubmit="submitReply(event,'${recipientId}')"><div class="field"><label>Penerima</label><input readonly value="${esc(r.name)}"></div><div class="field" style="margin-top:10px"><label>Judul</label><input name="subject" required value="Re: ${esc(subject)}"></div><div class="field" style="margin-top:10px"><label>Balasan</label><textarea name="body" rows="5" required></textarea></div><div class="modal-actions"><button type="button" class="btn btn-outline" onclick="closeModal()">Batal</button><button class="btn btn-primary">Kirim tanggapan</button></div></form>`)}
  async function submitReply(e,id){e.preventDefault();const f=new FormData(e.target);try{const r=await call('sendAcademicMessage',state.token,{targetType:'USER',targetId:id,subject:f.get('subject'),body:f.get('body'),replyTo:(state.messageRows||[]).find(m=>m.senderId===id)?.id||''});closeModal();toast(r.message);await renderMessages()}catch(err){toast(err.message,'error')}}
  async function openMessageModal(){try{const isStudent=state.user.role==='SISWA';const data=isStudent?{teachers:await call('getAcademicRecipients',state.token)}:await call('getAcademicRecipientOptions',state.token);state.messageRecipientOptions=data;const periods=data.periods||[];const periodOptions=periods.map(p=>`<option value="${p.id}">${esc(p.year)} · Semester ${esc(p.semester)}</option>`).join('');const classes=data.classes||[];const classOptions=classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');const students=data.students||[];if(isStudent&&!data.teachers.length)return toast('Belum ada guru aktif sebagai penerima.','error');openModal('Tulis pesan akademik',`<form id="academicMessageForm" onsubmit="submitMessage(event)">${isStudent?`<div class="field"><label>Penerima guru</label><select name="recipientId" required>${data.teachers.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div>`:`<div class="field"><label>Jenis penerima</label><select name="targetType" id="messageTargetType" onchange="updateMessageTargetFields()"><option value="USER">Satu siswa tertentu</option><option value="CLASS">Seluruh siswa dalam kelas</option><option value="CLASSES">Beberapa kelas sekaligus</option><option value="GRADE">Seluruh siswa tingkat 7 / 8 / 9</option><option value="PERIOD">Seluruh siswa dalam satu periode</option><option value="ALL">Semua siswa (seluruh sekolah)</option></select></div><div id="messageTargetFields"></div><div id="messageRecipientPreview" class="notice" style="margin-top:10px">Penerima akan dihitung sesuai pilihan.</div>`}<div class="field" style="margin-top:10px"><label>Judul pesan</label><input name="subject" required minlength="2"></div><div class="field" style="margin-top:10px"><label>Isi pesan</label><textarea name="body" rows="5" required minlength="2"></textarea></div><div class="modal-actions"><button type="button" class="btn btn-outline" onclick="closeModal()">Batal</button><button class="btn btn-primary">Kirim pesan</button></div></form>`);if(!isStudent)updateMessageTargetFields()}catch(e){toast(e.message,'error')}}
  function updateMessageTargetFields(){const box=$('messageTargetFields'),preview=$('messageRecipientPreview'),type=$('messageTargetType')?.value;if(!box||!type)return;const d=state.messageRecipientOptions||{},classes=d.classes||[],periods=d.periods||[],students=d.students||[];let html='';if(type==='USER'){html=`<div class="field"><label>Cari/pilih siswa</label><select name="targetId" required>${optionEmpty(students.length?'Pilih siswa':'Tidak ada siswa aktif')}${students.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.nisn)} · ${esc((classes.find(c=>c.id===s.classId)||{}).name||'Kelas belum ditentukan')}</option>`).join('')}</select></div>`}if(['CLASS','CLASSES','GRADE','PERIOD'].includes(type)){html+=`<div class="field" style="margin-top:10px"><label>Periode akademik</label><select name="periodId" required><option value="">Pilih periode</option>${periods.map(p=>`<option value="${esc(p.id)}">${esc(p.year)} · Semester ${esc(p.semester)}</option>`).join('')||''}</select></div>`}if(type==='CLASS')html+=`<div class="field" style="margin-top:10px"><label>Kelas</label><select name="classId" required><option value="">Pilih kelas</option>${classes.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div>`;if(type==='CLASSES')html+=`<div class="field" style="margin-top:10px"><label>Pilih beberapa kelas</label><div class="check-grid">${classes.map(c=>`<label class="check-row"><input type="checkbox" name="classIds" value="${esc(c.id)}"> ${esc(c.name)}</label>`).join('')||'<small class="muted">Belum ada kelas aktif.</small>'}</div></div>`;if(type==='GRADE')html+=`<div class="field" style="margin-top:10px"><label>Tingkat kelas</label><select name="grade" required><option value="">Pilih tingkat</option><option value="7">Kelas 7</option><option value="8">Kelas 8</option><option value="9">Kelas 9</option></select></div>`;box.innerHTML=html;const update=()=>{const f=$('academicMessageForm');if(!f)return;const fd=new FormData(f),periodId=fd.get('periodId')||'',classIds=fd.getAll('classIds'),classId=fd.get('classId')||'',grade=fd.get('grade')||'';let list=students;if(type==='USER')list=students.filter(s=>!!fd.get('targetId')&&s.id===fd.get('targetId'));if(type==='CLASS')list=students.filter(s=>s.classId===classId);if(type==='CLASSES')list=students.filter(s=>classIds.includes(s.classId));if(type==='GRADE')list=students.filter(s=>String(s.grade)===String(grade));if(type==='PERIOD'||type==='ALL')list=students.slice();if(type!=='USER'&&type!=='ALL')list=list.filter(s=>!periodId||(s.periodIds||[]).includes(periodId));preview.textContent='Perkiraan penerima: '+list.length+' siswa. Jumlah akhir divalidasi kembali oleh server saat pesan dikirim.'};box.querySelectorAll('select,input').forEach(el=>el.addEventListener('change',update));update()}
  async function submitMessage(e){e.preventDefault();const f=new FormData(e.target),isStudent=state.user.role==='SISWA';if(isStudent&&!f.get('recipientId'))return toast('Pilih guru penerima terlebih dahulu.','error');if(!isStudent&&f.get('targetType')==='USER'&&!f.get('targetId'))return toast('Pilih siswa penerima terlebih dahulu.','error');if(!isStudent&&['CLASS','CLASSES','GRADE','PERIOD'].includes(f.get('targetType'))&&!f.get('periodId'))return toast('Pilih periode akademik terlebih dahulu.','error');if(!isStudent&&f.get('targetType')==='CLASS'&&!f.get('classId'))return toast('Pilih kelas penerima terlebih dahulu.','error');if(!isStudent&&f.get('targetType')==='CLASSES'&&!f.getAll('classIds').length)return toast('Pilih minimal satu kelas penerima.','error');if(!isStudent&&f.get('targetType')==='GRADE'&&!f.get('grade'))return toast('Pilih tingkat kelas terlebih dahulu.','error');const data={targetType:isStudent?'USER':f.get('targetType'),targetId:isStudent?f.get('recipientId'):f.get('targetId'),periodId:f.get('periodId'),classId:f.get('classId'),classIds:f.getAll('classIds'),grade:f.get('grade'),subject:f.get('subject'),body:f.get('body')};loading(true);try{const r=await call('sendAcademicMessage',state.token,data);closeModal();toast(r.message,'success');await renderMessages()}catch(err){toast(err.message,'error')}finally{loading(false)}}


  async function loadStudentDashboardProgress(){try{const d=await call('getStudentReport',state.token,'','',((state.data.student||{}).periodId||''));const r=d.report,box=$('studentProgressPanel');if(!box)return;if(!r){box.innerHTML='<div class="panel-title">Progres belajar</div><div class="empty">Grafik dan ranking akan tampil setelah nilai mulai tersedia.</div>';return;}const categories=['TUGAS','PRAKTIK','PAS/PAT','LAINNYA'];const vals=categories.map(cat=>{const arr=d.columns.map((c,i)=>({c,v:r.scores[i]?.score})).filter(x=>String(x.c.category).toUpperCase()===cat&&x.v!==null&&x.v!==undefined);return arr.length?arr.reduce((a,x)=>a+Number(x.v),0)/arr.length:0});const max=Math.max(100,...vals),pts=vals.map((v,i)=>{const a=(-Math.PI/2)+(i*2*Math.PI/4),rr=25+(v/max)*70;return `${110+rr*Math.cos(a)},${95+rr*Math.sin(a)}`}).join(' ');box.innerHTML=`<div class="panel-head"><div><div class="panel-title">Progres belajar Anda</div><div class="panel-desc">Grafik berdasarkan rata-rata komponen nilai yang sudah terisi.</div></div><span class="badge badge-active">🏆 Peringkat ${r.rank||'—'}</span></div><div style="display:flex;align-items:center;gap:24px;flex-wrap:wrap"><svg viewBox="0 0 220 190" style="width:220px;max-width:100%;height:auto"><polygon points="110,25 180,95 110,165 40,95" fill="none" stroke="#dbe3f2"/><polygon points="110,48 157,95 110,142 63,95" fill="none" stroke="#e7ecf5"/><polygon points="${pts}" fill="rgba(82,91,220,.22)" stroke="#5965df" stroke-width="2"/><text x="110" y="13" text-anchor="middle" font-size="9" fill="#63718c">Tugas/PR</text><text x="198" y="98" text-anchor="middle" font-size="9" fill="#63718c">Praktik</text><text x="110" y="183" text-anchor="middle" font-size="9" fill="#63718c">PAS/PAT</text><text x="20" y="98" text-anchor="middle" font-size="9" fill="#63718c">Lainnya</text></svg><div><div class="stat-label">Rata-rata nilai</div><div class="stat-value">${r.average??'—'}</div><div class="stat-label" style="margin-top:8px">Predikat</div><b>${esc(r.predicate||'Belum ada nilai')}</b></div></div>`}catch(e){const b=$('studentProgressPanel');if(b)b.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
