  async function submitPeriod(e,id){e.preventDefault();const f=new FormData(e.target);const year=String(f.get('year')||'').trim(),start=String(f.get('startDate')||''),end=String(f.get('endDate')||'');const years=year.match(/^(\d{4})\/(\d{4})$/);if(!years||Number(years[2])!==Number(years[1])+1)return toast('Tahun ajaran harus berurutan, misalnya 2026/2027.','error');if(!start||!end||end<start)return toast('Tanggal selesai harus sama atau setelah tanggal mulai.','error');const duplicate=(state.data.periods||[]).find(p=>p.id!==id&&p.status!=='ARCHIVED'&&p.year===year&&String(p.semester)===String(f.get('semester')));if(duplicate)return toast(`Tahun ajaran ${year} Semester ${f.get('semester')} sudah terdaftar.`,'error');loading(true);try{const r=await call('savePeriod',state.token,{id,year,semester:f.get('semester'),startDate:start,endDate:end});closeModal();state.pageNo=1;await refreshData();toast(r.message);}catch(err){toast(err.message,'error')}finally{loading(false)}}
