  function openPasswordModal(force){openModal(force?'Perbarui kata sandi awal':'Ubah kata sandi',`<p class="muted" style="font-size:11px;line-height:1.5">${force?'Demi keamanan, Anda harus mengganti kata sandi sementara sebelum melanjutkan.':'Gunakan kata sandi yang kuat dan jangan membagikannya.'}</p><form onsubmit="submitPassword(event)"><div class="field"><label>Kata sandi saat ini</label><input name="current" type="password" required autocomplete="current-password"></div><div class="field" style="margin-top:10px"><label>Kata sandi baru</label><input name="next" type="password" minlength="8" required autocomplete="new-password"></div><div class="field" style="margin-top:10px"><label>Ulangi kata sandi baru</label><input name="confirm" type="password" minlength="8" required autocomplete="new-password"></div><div class="modal-actions">${force?'':`<button type="button" class="btn btn-outline" onclick="closeModal()">Batal</button>`}<button class="btn btn-primary">Simpan kata sandi</button></div></form>`,force)}
